  assert.deepEqual(result.trace.map(node => node.nodeId),
    ['start', 'hold', 'branch-a', 'branch-b', 'done']);
  assert.deepEqual(Object.keys(result.context.output), ['hold', 'branch-a', 'branch-b']);
