38	      waitNode,
39	      gateNode,
40	      { id: 'approved', type: 'end', result: 'approved' },
41	      { id: 'rejected', type: 'end', result: 'rejected' },
42	      ...extraNodes,
43	    ],
44	  };
45	  return { workflow, gateNode, waitNode };
